function calculateTotal(items: Item[]) {
  let total = 0;
  for (const i of items) {
    total += i.price * i.quantity;
  }
  sendAnalytics(total);
}

function invoice(items: Item[]) {
  let total = 0;
  for (const i of items) {
    total += i.price * i.quantity;
  }
  return total;
}

function buildReport(data: Data[]) {
  const summary = computeSummary(data);
  if (summary.empty) {
    const formatted = formatSummary(summary);
    console.log("Empty report", formatted);
    return formatted;
  }
  const formattedFull = formatSummary(summary);
  saveReport(formattedFull);
  console.log("Report saved", formattedFull);
  return formattedFull;
}

