function publish(item, user, config) {
  const formatted = format(item, config.format);
  if (!authorize(user, item)) {
    audit(user, item, 'denied');
    return;
  }
  audit(user, item, 'published');
  send(formatted, config.destination, user.email);
}

// Version B
function publish(item, ctx) {
  const formatted = format(item, ctx.format);
  if (!authorize(ctx.user, item)) {
    ctx.audit('denied');
    return;
  }
  ctx.audit('published');
  send(formatted, ctx.destination, ctx.user.email);
}
